{
  "name": "opencode-better-eyesight",
  "version": "0.1.1",
  "description": "Vision plugin for opencode: ask any model opencode has access to about images (clipboard, files, URLs, session attachments), with parent-prompt forwarding, session history and caching.",
  "type": "module",
  "main": "./index.ts",
  "license": "MIT",
  "author": "entrptaher",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/entrptaher/opencode-better-eyesight.git"
  },
  "keywords": ["opencode", "opencode-plugin", "vision", "image", "screenshot", "clipboard"],
  "files": ["index.ts", "src"],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.18"
  },
  "devDependencies": {
    "@opencode-ai/sdk": "1.18.18",
    "@types/bun": "1.3.10",
    "typescript": "5.9.3"
  }
}
